const T_START = .3;
const tau = Math.max(0, t - T_START);          // 1배속: 영상 시간 = 장면 시간
ball = ballAt(tau);

const SLOW = .3, FAST = 1.4;
function speed(c) {                              // c: 장면 시간
  if (c < .8) return 1;
  if (c < 1.2) return lerp(1, SLOW, easeInOut((c - .8) / .4));
  if (c < 1.9) return SLOW;
  if (c < 2.3) return lerp(SLOW, FAST, easeInOut((c - 1.9) / .4));
  return FAST;
}
tau += speed(tau) * dt;                          // dt = 1/240초씩 쌓아 표로 만듦

const FZ = 2.0, FREEZE = .8, VIGN = .55;
if (tau >= FZ && held < FREEZE) { held += dt; /* τ 는 그대로 */ }
vignette = radialGradient(transparent → rgba(0,0,0,VIGN));   // 정지 중에만
